style.css:
@-moz-document domain("play.pokemonshowdown.com") {
/* ===== BACKGROUND (IMMERSION) ===== */
body {
    background: radial-gradient(circle at center, #0a0a0a 0%, #000000 100%) !important;
    color: #eaeaea !important;
    font-family: "Segoe UI", sans-serif !important;
}

/* ===== LAYOUT: CENTERED CINEMA ===== */
#ps-frame, #main, .ps-room {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    height: 100vh !important;
    width: 100% !important;
}

/* ===== BATTLE STAGE ===== */
.battle {
    order: 1 !important;
    width: 90% !important;
    max-width: 1100px !important;
    flex: 1 !important;

    border-radius: 16px !important;
    overflow: hidden !important;

    box-shadow:
        0 0 40px rgba(0,0,0,0.9),
        0 0 80px rgba(0,0,0,0.6) inset !important;

    background: linear-gradient(180deg, #111 0%, #000 100%) !important;
}

/* Battle visuals bigger */
.battle canvas, .innerbattle {
    width: 100% !important;
    height: auto !important;
}

/* ===== REMOVE CLUTTER ===== */
.userlist, .rightbar, .leftbar, .roomlist {
    display: none !important;
}

/* ===== CHAT = CONTROL PANEL ===== */
.chat, .chat-log {
    order: 2 !important;
    width: 90% !important;
    max-width: 1100px !important;

    margin-top: 10px !important;
    padding: 10px !important;

    border-radius: 12px !important;
    background: rgba(10,10,10,0.95) !important;

    box-shadow:
        0 0 20px rgba(0,0,0,0.8),
        0 0 10px rgba(255,255,255,0.05) inset !important;

    max-height: 220px !important;
    overflow-y: auto !important;
}

/* ===== CHAT TEXT GLOW ===== */
.chat-log {
    font-size: 15px !important;
    line-height: 1.5 !important;
}

.chat-log strong {
    color: #7fdcff !important;
}

/* ===== BUTTONS (MOVES) ===== */
button {
    border-radius: 10px !important;
    border: none !important;
    padding: 10px !important;

    background: linear-gradient(145deg, #1a1a1a, #0d0d0d) !important;
    color: #fff !important;

    box-shadow:
        0 0 10px rgba(255,255,255,0.05),
        0 0 20px rgba(0,0,0,0.8) inset !important;

    transition: all 0.2s ease !important;
}

/* Button hover glow */
button:hover {
    transform: scale(1.05) !important;
    box-shadow:
        0 0 12px rgba(127,220,255,0.6),
        0 0 30px rgba(0,0,0,0.9) inset !important;
}

/* ===== HEALTH BARS POP ===== */
.hpbar {
    filter: drop-shadow(0 0 6px rgba(0,255,0,0.6)) !important;
}

/* ===== TEXT CLEAN ===== */
body {
    font-size: 16px !important;
}

/* ===== FORCE STACKING ===== */
.ps-room, .ps-room > div {
    display: flex !important;
    flex-direction: column !important;
    width: 100% !important;
}
}
